// ItemsCount says "{count, plural, one {# item} other {# items}}"
// in the language the app shows under cx.
func ItemsCount(cx *core.Scope, count int) string { return For(cx).ItemsCount(count) }

// ItemsCount is the package's ItemsCount in the language of msgs.
func (msgs Messages) ItemsCount(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.ItemsCount(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ItemsCount; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" item")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" items")
			}
			return b.String()
		case "zh-Hans":
			var b strings.Builder
			switch i18n.Cardinal("zh-Hans", float64(count)) {
			default:
				b.WriteString(i18n.FormatNumber("zh-Hans", float64(count)))
				b.WriteString(" 个项目")
			}
			return b.String()
		}
	}
}

